-- Synthetic identities only. Run in a rollback transaction after the migration.
begin;
do $tests$
declare c uuid:=gen_random_uuid();other_c uuid:=gen_random_uuid();adm uuid:=gen_random_uuid();head_id uuid:=gen_random_uuid();
 viewer uuid:=gen_random_uuid();editor uuid:=gen_random_uuid();other_head uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();invitee uuid:=gen_random_uuid();
 g1 uuid:=gen_random_uuid();g2 uuid:=gen_random_uuid();grade1 uuid:=gen_random_uuid();grade2 uuid:=gen_random_uuid();f1 uuid:=gen_random_uuid();f2 uuid:=gen_random_uuid();u uuid;
 ctx jsonb;payload jsonb;result jsonb;retry jsonb;details1 jsonb;details2 jsonb;rejected boolean;token text:=repeat('a',64);revision text;req uuid;
begin
 foreach u in array array[adm,head_id,viewer,editor,other_head,outsider,invitee] loop
  insert into auth.users(id,email,email_confirmed_at) values(u,u||'@example.invalid',now());
  insert into public.user_profiles(user_id,display_name) values(u,'Synthetic permission test');
 end loop;
 insert into public.clubs(id,name,slug,created_by) values(c,'Permission test','permission-'||c,adm),(other_c,'Other club','permission-'||other_c,outsider);
 insert into public.club_memberships(club_id,user_id,role,permission_role) values(c,adm,'admin','admin'),(c,head_id,'player','none'),(c,viewer,'player','none'),(c,editor,'player','none'),(c,other_head,'player','none'),(other_c,outsider,'player','none');
 insert into club_selection_private.access(club_id,mode,status,timezone,head_selector_id,revision) values(c,'standalone','active','Australia/Sydney',head_id,1);
 insert into club_selection_private.selectors(club_id,user_id) values(c,editor);
 insert into club_selection_private.selection_groups(id,club_id,name) values(g1,c,'Saturday'),(g2,c,'Masters');
 insert into public.playing_groups(id,club_id,name,active) values(grade1,c,'First XI',true),(grade2,c,'Masters XI',true);
 insert into club_selection_private.selection_group_grades(club_id,selection_group_id,grade_id) values(c,g1,grade1),(c,g2,grade2);
 details1:=jsonb_build_object('grade','First XI','grade_group_id',grade1,'days',jsonb_build_array(jsonb_build_object('date','2099-01-01')));
 details2:=jsonb_build_object('grade','Masters XI','grade_group_id',grade2,'days',jsonb_build_array(jsonb_build_object('date','2099-01-01')));
 insert into club_selection_private.fixtures(id,club_id,details,slots,revision) values(f1,c,details1,'[]',1),(f2,c,details2,'[]',1);
 assert not club_selection_private.scoped_selections(c),'Existing clubs remain unchanged before explicit permission save';
 assert club_selection_private.selector(c,editor),'Legacy selector access retained before activation';
 perform set_config('request.jwt.claim.sub',adm::text,true);
 ctx:=public.selection_group_permissions(c,'context');
 payload:=jsonb_build_object('group_id',g1,'head_id',head_id,'revision',ctx->>'revision','request_id',gen_random_uuid(),'members',jsonb_build_array(jsonb_build_object('user_id',head_id,'access','edit'),jsonb_build_object('user_id',viewer,'access','view'),jsonb_build_object('user_id',editor,'access','edit')));
 result:=public.selection_group_permissions(c,'save_group',payload);
 retry:=public.selection_group_permissions(c,'save_group',payload);assert retry=result,'Identical permission retry is idempotent';
 assert club_selection_private.scoped_selections(c),'Explicit save enables group scope';
 assert club_selection_private.selection_group_level(c,g1,viewer)=1 and club_selection_private.selection_group_level(c,g2,viewer)=0,'View grant applies to exact group only';
 assert not club_selection_private.selector(c,viewer),'View-only grant never gains legacy global mutation rights';
 assert club_selection_private.selection_group_level(c,g2,editor)=2,'Activation preserves existing other-group access';
 assert club_selection_private.selection_group_level(c,g1,adm)=0,'Admin is not automatically a selector';
 assert club_selection_private.selection_group_level(c,g1,outsider)=0,'Cross-club user denied';
 rejected:=false;begin perform public.selection_group_permissions(c,'save_group',payload||jsonb_build_object('request_id',gen_random_uuid()));exception when raise_exception then rejected:=sqlerrm like '%Permissions changed%';end;assert rejected,'Stale revision cannot alter permissions';
 ctx:=public.selection_group_permissions(c,'context');
 payload:=jsonb_build_object('group_id',g2,'head_id',other_head,'revision',ctx->>'revision','request_id',gen_random_uuid(),'members',jsonb_build_array(jsonb_build_object('user_id',other_head,'access','edit'),jsonb_build_object('user_id',head_id,'access','view')));
 perform public.selection_group_permissions(c,'save_group',payload);
 assert club_selection_private.fixture_publisher(c,details2)=other_head,'Group Head publishes independently';
 assert club_selection_private.selection_group_level(c,g2,head_id)=1,'Global Head can relinquish group editing and retain view';
 assert club_selection_private.fixture_publisher(c,details1)=head_id,'Other group publishing remains unchanged';
 assert club_selection_private.selection_group_level(c,g2,editor)=0 and not club_selection_private.selector(c,editor),'Partial-group editor cannot use legacy club-wide mutation endpoints';
 assert club_selection_private.selection_editor(c,editor) and club_selection_private.selection_viewer(c,editor),'Partial editor retains scoped editor/viewer access';
 ctx:=public.selection_group_permissions(c,'context');
 rejected:=false;begin perform public.selection_group_permissions(c,'save_group',payload||jsonb_build_object('head_id',null,'revision',ctx->>'revision','request_id',gen_random_uuid()));exception when raise_exception then rejected:=sqlerrm like '%Appoint a Head Selector%';end;assert rejected,'No group can be saved without publishing authority';
 rejected:=false;begin delete from public.club_memberships where club_id=c and user_id=other_head;exception when raise_exception then rejected:=sqlerrm like '%replacement Head Selectors%';end;assert rejected,'Cannot remove active group Head';
 perform set_config('request.jwt.claim.sub',viewer::text,true);
 assert club_selection_private.selection_view(c,details1,viewer) and not club_selection_private.selection_edit(c,details1,viewer),'View and edit remain distinct';
 rejected:=false;begin perform club_selection_private.api(c,'save_board',jsonb_build_object('request_id',gen_random_uuid(),'fixtures',jsonb_build_array(jsonb_build_object('id',f1,'revision',1,'slots','[]'::jsonb))));exception when raise_exception then rejected:=sqlerrm like '%requires its editor%';end;assert rejected,'Old browser write rejected server-side for view-only user';
 rejected:=false;begin perform club_selection_private.api(c,'publish',jsonb_build_object('request_id',gen_random_uuid(),'ids',jsonb_build_array(f1)));exception when raise_exception then rejected:=sqlerrm like '%requires its editor%';end;assert rejected,'View-only user cannot publish';
 assert club_selection_private.selection_room_scope(c,jsonb_build_object('selection_group_id',g1))=g1,'Room scope permits assigned view';
 rejected:=false;begin perform club_selection_private.selection_room_scope(c,jsonb_build_object('selection_group_id',g2));exception when insufficient_privilege then rejected:=true;end;assert rejected,'Room scope denies other group';
 rejected:=false;begin perform club_selection_private.selection_room_scope(c,'{}');exception when insufficient_privilege then rejected:=true;end;assert rejected,'Stale unscoped room client denied after activation';
 rejected:=false;begin perform club_selection_private.selection_room_api_before_credits(c,'post',jsonb_build_object('selection_group_id',g1,'request_id',gen_random_uuid(),'body','View only'));exception when insufficient_privilege then rejected:=true;end;assert rejected,'View-only participant cannot post selection chat';
 perform set_config('request.jwt.claim.sub',editor::text,true);
 rejected:=false;begin perform club_selection_private.api(c,'save_board',jsonb_build_object('request_id',gen_random_uuid(),'fixtures',jsonb_build_array(jsonb_build_object('id',f2,'revision',1,'slots','[]'::jsonb))));exception when raise_exception then rejected:=sqlerrm like '%requires its editor%';end;assert rejected,'Editor cannot save another group';
 rejected:=false;begin perform club_selection_private.api(c,'publish',jsonb_build_object('request_id',gen_random_uuid(),'ids',jsonb_build_array(f1)));exception when raise_exception then rejected:=sqlerrm like '%requires its editor%';end;assert rejected,'Editor cannot replace Head publication authority';
 perform set_config('request.jwt.claim.sub',adm::text,true);
 ctx:=public.selection_group_permissions(c,'context');
 payload:=jsonb_build_object('group_id',g2,'revision',ctx->>'revision','request_id',gen_random_uuid(),'name','Invited viewer','email',invitee||'@example.invalid','access','view','as_head',false,'token',token);
 perform public.selection_group_permissions(c,'invite',payload);
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 rejected:=false;begin perform public.selection_group_invitation(token,'accept');exception when raise_exception then rejected:=sqlerrm like '%verified email%';end;assert rejected,'Invitation requires exact verified email';
 perform set_config('request.jwt.claim.sub',invitee::text,true);
 result:=public.selection_group_invitation(token,'accept');retry:=public.selection_group_invitation(token,'accept');assert result=retry,'Invitation acceptance is idempotent';
 assert club_selection_private.selection_group_level(c,g2,invitee)=1 and club_selection_private.selection_group_level(c,g1,invitee)=0,'Invitation retains exact group and view permission';
 assert not club_selection_private.selector(c,invitee),'Invitation does not grant global selector writes';
 assert club_selection_private.selection_scorecard_edit(c,jsonb_build_object('grade','First XI'),editor),'Group editor can stage its own unlinked scorecard';
 assert not club_selection_private.selection_scorecard_edit(c,jsonb_build_object('grade','Masters XI'),editor),'Group editor cannot stage another group scorecard';
 assert not club_selection_private.selection_scorecard_edit(c,jsonb_build_object('grade','First XI'),viewer),'Read-only access cannot stage scorecard changes';
 assert club_selection_private.fixture_ids_allowed(c,jsonb_build_array(jsonb_build_object('id',f1)),head_id,'publish'),'Group publisher can publish its fixture';
 assert not club_selection_private.fixture_ids_allowed(c,jsonb_build_array(jsonb_build_object('id',f1),jsonb_build_object('id',f2)),head_id,'publish'),'Publishing cannot mix unauthorized groups';
 assert not club_selection_private.fixture_ids_allowed(c,jsonb_build_array(jsonb_build_object('id',gen_random_uuid())),head_id,'publish'),'Unknown fixture never bypasses publication scope';
 assert not has_table_privilege('authenticated','club_selection_private.selection_group_access','select'),'Private grants are not directly readable';
 assert not has_function_privilege('authenticated','club_selection_private.selection_viewer(uuid,uuid)','execute'),'Private helper cannot be called directly';
end $tests$;
rollback;
